            ok = false;
        }

        // Single assertion: the reference contract must never revert for any bytes4 interfaceId (supportsInterface is view and should return a bool)
        // The mutant will still typically not revert, but will return different booleans for some inputs. This assertion distinguishes the mutant because
        // the reference property is that supportsInterface always completes (does not revert) for any bytes4; the mutant preserves this too,
